const cfg=window.FIREBASE_CONFIG;const app=firebase.initializeApp(cfg);const db=firebase.firestore();const $=s=>document.querySelector(s);let data=null,currentPeriod='P1',currentCourse='Tecnología';function norm(v=''){return String(v).toUpperCase().replace(/[^A-Z0-9]/g,'')}async function docId(code,pin){const raw=`${norm(code)}|${String(pin).trim()}`;const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(raw));return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('')}function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function fmtDate(s){if(!s)return'';return new Date(s+'T12:00:00').toLocaleDateString('es-MX',{day:'numeric',month:'short',year:'numeric'})}async function enter(){const code=$('#code').value,pin=$('#pin').value.trim(),err=$('#error');err.textContent='';if(!code||pin.length!==4){err.textContent='Revisa la clave y el PIN.';return}try{const id=await docId(code,pin),snap=await db.collection('family_portal').doc(id).get();if(!snap.exists){err.textContent='La clave o el PIN no son correctos.';return}data=snap.data();$('#loginCard').hidden=true;$('#portal').hidden=false;render()}catch(e){console.error(e);err.textContent='No fue posible consultar la información. Intenta nuevamente.'}}function courseData(){return data?.periods?.[currentPeriod]?.courses?.[currentCourse]||null}function render(){const p=data.periods?.[currentPeriod],courses=Object.keys(p?.courses||{});if(!courses.includes(currentCourse))currentCourse=courses[0]||'Tecnología';const c=courseData(),a=data.attendance||{};const g=c?.grade||{},acts=c?.activities||[],done=acts.filter(x=>Number(x.score)>0).length,pending=acts.filter(x=>x.score===0).length;$('#portal').innerHTML=`<div class="portal-head"><div><div class="eyebrow">${esc(data.student.shift)} · ${esc(data.student.group)}</div><h1>${esc(data.student.name)}</h1><div class="badges"><span class="badge">${esc(currentCourse)}</span><span class="badge">${esc(p?.name||currentPeriod)}</span></div></div><button class="secondary" id="logout">Cambiar alumno</button></div><div class="cards"><div class="card metric"><strong>${a.percentage===null?'—':a.percentage+'%'}</strong><span>Asistencia</span></div><div class="card metric"><strong>${done}</strong><span>${done} de ${acts.length} actividades evaluadas</span></div><div class="card metric"><strong>${pending}</strong><span>Actividades pendientes</span></div><div class="card metric"><strong>${g.grade==null?'—':Number(g.grade).toFixed(1)}</strong><span>${g.complete?'Calificación final':'Calificación provisional'}</span></div></div><div class="toolbar"><label>Periodo <select id="period">${Object.entries(data.periods||{}).map(([id,x])=>`<option value="${id}" ${id===currentPeriod?'selected':''}>${esc(x.name||id)}</option>`).join('')}</select></label><label>Asignatura <select id="course">${courses.map(x=>`<option ${x===currentCourse?'selected':''}>${esc(x)}</option>`).join('')}</select></label></div><section class="card section"><h2>Calificación</h2>${gradeHtml(g)}</section><section class="card section"><h2>Asistencia acumulada</h2><p>${a.present||0} asistencias · ${a.absent||0} faltas · ${a.justified||0} justificadas · ${a.late||0} retardos</p></section><section class="section"><h2>Actividades</h2><div class="activity-list">${acts.length?acts.map(activityHtml).join(''):'<div class="card">Aún no hay actividades registradas para este periodo.</div>'}</div></section>${noticeSection('Avisos individuales',c?.followups||[])}${journalSection(c?.journal||[])}<p class="updated">Última actualización del portal: ${esc(data.updatedLabel||'')}</p>`;$('#logout').onclick=()=>location.reload();$('#period').onchange=e=>{currentPeriod=e.target.value;render()};$('#course').onchange=e=>{currentCourse=e.target.value;render()}}function gradeHtml(g){const w=g.weights||{},parts=[['Actividades',g.activityPoints,w.activities],['Proyecto',g.project,w.project],['Examen',g.exam,w.exam]].filter(x=>Number(x[2]||0)>0);return `<div class="grade-box">${parts.map(x=>`<div class="grade-part"><b>${x[1]==null||x[1]==='NA'?'—':Number(x[1]).toFixed(1)} / ${x[2]}</b><span>${x[0]}</span></div>`).join('')}<div class="grade-part"><b>${g.grade==null?'—':Number(g.grade).toFixed(1)}</b><span>${g.complete?'Final':'Provisional'}</span></div></div>`}function activityHtml(x){const cls=x.score===0?'pending':x.score==null?'neutral':'done',label=x.score===0?'Pendiente':x.score==null?'Aún no evaluada':`${x.score}/${x.max}`;return `<div class="activity"><div><b>${esc(x.name)}</b><small>${fmtDate(x.date)}${x.detail?' · '+esc(x.detail):''}</small></div><div class="status ${cls}">${label}</div></div>`}function noticeSection(title,items){if(!items.length)return'';return `<section class="section"><h2>${title}</h2><div class="notice-list">${items.map(x=>`<div class="notice"><b>${esc(x.title||x.category||'Aviso')}</b><small> · ${fmtDate(x.date)}</small><p>${esc(x.text||'')}</p></div>`).join('')}</div></section>`}function journalSection(items){if(!items.length)return'';return `<section class="section"><h2>Avisos de clase</h2><div class="notice-list">${items.map(x=>`<div class="notice"><b>${esc(x.title)}</b><small> · ${fmtDate(x.date)}</small><p>${esc(x.text||'')}</p>${x.pending?`<p><b>Pendiente:</b> ${esc(x.pending)}</p>`:''}${(x.attachments||[]).map(a=>`<a href="${esc(a.url)}" target="_blank" rel="noopener">📄 ${esc(a.title)}</a>`).join('')}</div>`).join('')}</div></section>`}$('#enter').onclick=enter;$('#pin').addEventListener('keydown',e=>{if(e.key==='Enter')enter()});
